import { useEffect, useRef, useState } from 'react';
import { Map as MaplibreMap } from 'maplibre-gl';
import 'maplibre-gl/dist/maplibre-gl.css';
import { hasGeneratedMapData, loadGeneratedMapGeoJson } from './mapDataAvailability';

interface RealMapPanelProps {
  className?: string;
}

/**
 * Renders the real ETS2 road network generated by
 * tools/GERAR_MAPA_ETS2.ps1 (truckermudgeon/maps, GPL-3.0) via MapLibre GL.
 *
 * STATUS (Fase 10, first version — see docs/ETS2_ARCHITECTURE.md "Mapa
 * real" for the full breakdown): renders the static road/prefab layer once
 * map data has been generated for the user's own ETS2 install. Does
 * **not** yet plot a live truck marker — that needs the exact affine
 * transform truckermudgeon/maps' generator uses to go from ETS2 world
 * coordinates (what `truck.world.placement` telemetry gives us, in
 * meters) to this map's projection, which was not inspected in this
 * coding session (no access to a generated dataset or the running game to
 * validate the alignment against). Shipping a guessed transform here
 * would silently show the truck in the wrong place, which the Fase 10
 * task explicitly prohibits ("validar alinhamento com amostras de
 * telemetria") — so this component honestly stops at the static map for
 * now. Not wired into Dashboard/NavegacaoScreen yet for the same reason:
 * those screens' approved mock visuals stay untouched until the live
 * marker is real.
 */
export function RealMapPanel({ className }: RealMapPanelProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const mapRef = useRef<MaplibreMap | null>(null);
  const [status, setStatus] = useState<'no-data' | 'loading' | 'ready' | 'error'>('no-data');

  useEffect(() => {
    if (!hasGeneratedMapData()) {
      setStatus('no-data');
      return;
    }
    if (!containerRef.current) return;

    setStatus('loading');
    let cancelled = false;

    const map = new MaplibreMap({
      container: containerRef.current,
      style: {
        version: 8,
        sources: {},
        layers: [{ id: 'background', type: 'background', paint: { 'background-color': '#0b1c2c' } }],
      },
      center: [0, 0],
      zoom: 4,
      attributionControl: false,
    });
    mapRef.current = map;

    map.on('load', () => {
      void loadGeneratedMapGeoJson().then((geoJson) => {
        if (cancelled || !geoJson) {
          setStatus(geoJson ? 'ready' : 'error');
          return;
        }
        // GeoJSON.FeatureCollection isn't a MapLibre-specific type, so this
        // cast is just satisfying maplibre-gl's narrower GeoJSONSourceSpecification type.
        map.addSource('ets2-roads', { type: 'geojson', data: geoJson as never });
        map.addLayer({
          id: 'ets2-roads-line',
          type: 'line',
          source: 'ets2-roads',
          paint: { 'line-color': '#4fc3f7', 'line-width': 1.5 },
        });
        setStatus('ready');
      });
    });

    return () => {
      cancelled = true;
      map.remove();
      mapRef.current = null;
    };
  }, []);

  if (status === 'no-data') {
    return (
      <div className={className} style={mapPlaceholderStyle}>
        Mapa real do ETS2 ainda não foi gerado — rode tools/GERAR_MAPA_ETS2.ps1 (ver docs/ETS2_ARCHITECTURE.md).
      </div>
    );
  }

  return (
    <div className={className} style={{ position: 'relative', width: '100%', height: '100%' }}>
      <div ref={containerRef} style={{ width: '100%', height: '100%' }} />
      {status === 'error' && (
        <div style={{ ...mapPlaceholderStyle, position: 'absolute', inset: 0 }}>
          Dados de mapa gerados encontrados, mas não puderam ser lidos — rode tools/GERAR_MAPA_ETS2.ps1 de novo.
        </div>
      )}
    </div>
  );
}

const mapPlaceholderStyle: React.CSSProperties = {
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  textAlign: 'center',
  padding: 24,
  color: 'rgba(255,255,255,0.6)',
  fontSize: 14,
  background: '#0b1c2c',
  width: '100%',
  height: '100%',
  boxSizing: 'border-box',
};
